import { useEffect } from 'react';
import api from './api';

function App() {

  useEffect(() => {
    api.get('/')
      .then(res => console.log(res.data))
      .catch(err => console.log(err));
  }, []);

  return (
    <div>
      <h1>Alumni Connect</h1>
    </div>
  );
}

export default App;
